// ---------------------------------------------------------------------------
// Result<O, E>. `tag == 0` = ok, `tag == 1` = err. Both branches need a
// value of the appropriate type; for the inactive branch use a sentinel
// default (zero for primitives, changetype<T>(0) for classes).
// ---------------------------------------------------------------------------

export class Result<O, E> {
  constructor(public tag: i32, public okValue: O, public errValue: E) {}
  isOk(): bool { return this.tag == 0; }
  isErr(): bool { return this.tag == 1; }
}

